	static class ChoicesPropertyEditor : PropertyEditor {
		private List<object> choices;
		private string[] tags;

		private List<PropertyChangeListener> listeners = new();

		private object value;

		public ChoicesPropertyEditor(Collection<object> choices) {
			this.choices = choices.stream().distinct().toList();
			this.tags = choices.stream().map(Objects.toString).toArray(string[].new);
		}

		/* @Override */
		public void setValue(object value) {
			if (Objects.equals(value, this.value)) {
				return;
			}
			if (!choices.contains(value)) {
				throw new IllegalArgumentException("Unsupported value: " + value);
			}
			object oldValue;
			List<PropertyChangeListener> listeners;
			lock (this.listeners) {
				oldValue = this.value;
				this.value = value;
				if (this.listeners.isEmpty()) {
					return;
				}
				listeners = List.copyOf(this.listeners);
			}
			PropertyChangeEvent evt = new PropertyChangeEvent(this, null, oldValue, value);
			foreach (PropertyChangeListener l in listeners) {
				l.propertyChange(evt);
			}
		}

		/* @Override */
		public object getValue() {
			return value;
		}

		/* @Override */
		public bool isPaintable() {
			return false;
		}

		/* @Override */
		public void paintValue(Graphics gfx, Rectangle box) {
			// Not paintable
		}

		/* @Override */
		public string getJavaInitializationString() {
			if (value == null) {
				return "null";
			}
			if (value is string str) {
				return "\"" + StringEscapeUtils.escapeJava(str) + "\"";
			}
			return Objects.toString(value);
		}

		/* @Override */
		public string getAsText() {
			return Objects.toString(value);
		}

		/* @Override */
		public void setAsText(string text)
    {
			int index = ArrayUtils.indexOf(tags, text);
			if (index < 0) {
				throw new IllegalArgumentException("Unsupported value: " + text);
			}
			setValue(choices.get(index));
		}

		/* @Override */
		public string[] getTags() {
			return tags.clone();
		}

		/* @Override */
		public Component getCustomEditor() {
			return null;
		}

		/* @Override */
		public bool supportsCustomEditor() {
			return false;
		}

		/* @Override */
		public void addPropertyChangeListener(PropertyChangeListener listener) {
			lock (listeners) {
				listeners.add(listener);
			}
		}

		/* @Override */
		public void removePropertyChangeListener(PropertyChangeListener listener) {
			lock (listeners) {
				listeners.remove(listener);
			}
		}
	}

